// configured at all, which an empty RemoteURLs cannot express — a remote with
// only a pushurl has no fetch URL, and one whose url is empty has neither.
func (s Snapshot) Get(name string) (RemoteURLs, bool) {
	u, ok := s.urls[name]
	return u, ok
