		}
	}

	return CheckpointPushURL(ctx, PushDecision{
		Remote:           pushRemoteName,
		Config:           config,
		OriginURL:        originURL,
		RemoteFetchURL:   remoteFetchURL,
		PushURLs:         pushRemoteURLs,
		StoreIsLocalOnly: settings.CheckpointRemoteIsLocalOnly(ctx),
	})
}

